    "answer": "Penerapan K3 di Sektor Pembangkit Listrik Tenaga Panas Bumi (PLTP Geothermal) dirancang untuk mengelola risiko kecelakaan spesifik dan penyakit akibat kerja di sektor Pembangkit Listrik Tenaga Panas Bumi (PLTP Geothermal) melalui integrasi SMKP Minerba, Sistem Manajemen Keselamatan Migas & SMK3 PP 50/2012 serta penempatan personel K3 bersertifikasi resmi.",
