    "description": "Panduan implementasi K3 sektor Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm): identifikasi bahaya dominan, kerangka regulasi SMKP Minerba, Sistem Manajemen Keselamatan Migas & SMK3 PP 50/2012, kebutuhan lisensi personil, dan program mitigasi kecelakaan.",
    "answer": "Penerapan K3 di Sektor Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm) dirancang untuk mengelola risiko kecelakaan spesifik dan penyakit akibat kerja di sektor Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm) melalui integrasi SMKP Minerba, Sistem Manajemen Keselamatan Migas & SMK3 PP 50/2012 serta penempatan personel K3 bersertifikasi resmi.",
    "highlights": [
      "Sektor Industri: Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm)",
      "Kategori: Energi, Migas, Pertambangan & Mineral",
      "Kerangka Kepatuhan: SMKP Minerba, Sistem Manajemen Keselamatan Migas & SMK3 PP 50/2012",
      "Tujuan: Pengendalian Bahaya Kritis & Pencapaian Zero Accident Sektoral"
    ],
    "blocks": [
      {
        "heading": "Karakteristik Operasional & Profil Risiko Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm)",
        "paragraphs": [
          "Operasional di sektor Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm) memiliki profil bahaya yang khas dan memerlukan pendekatan keselamatan kerja terstruktur. Aktivitas di area ini melibatkan kombinasi risiko mekanikal, kelistrikan, bahan kimia berbahaya, serta faktor lingkungan kerja fisik yang berpotensi memicu kecelakaan parah jika tidak dikendalikan dengan ketat.",
          "Penerapan K3 berlandaskan SMKP Minerba, Sistem Manajemen Keselamatan Migas & SMK3 PP 50/2012 menjadi kewajiban mutlak bagi pengelola fasilitas guna melindungi keselamatan seluruh tenaga kerja, meminimalkan downtime operasional, dan memenuhi audit sertifikasi sistem manajemen."
        ]
      },
      {
        "heading": "Bahaya Kritis & Program Mitigasi Unggulan",
        "paragraphs": [
          "Program keselamatan yang wajib diterapkan mencakup:"
        ],
        "bullets": [
          "Penyusunan HIRADC spesifik yang memetakan titik kegagalan proses dan aktivitas risiko tinggi",
          "Penerapan sistem Izin Kerja Aman (Permit to Work) untuk pekerjaan berisiko tinggi",
          "Pelaksanaan pemeliharaan preventif dan riksa uji kelayakan berkala peralatan mesin/sarana pabrik",
          "Penyediaan Alat Pelindung Diri (APD) terstandar dan penegakan disiplin pemakaian di area kerja",
          "Pembentukan Tim Tanggap Darurat (Emergency Response Team) dan simulasi latihan berkala"
        ]
      },
      {
        "heading": "Kebutuhan Sertifikasi & Lisensi Personel K3",
        "paragraphs": [
          "Perusahaan pada sektor ini dipersyaratkan menunjuk tenaga kerja yang memiliki sertifikat pembinaan Ahli K3 Umum, Ahli K3 Spesialis sektoral terkait, auditor internal SMK3, serta operator berlisensi SIO Kemnaker RI."
        ]
      },
      {
        "heading": "Layanan Pendampingan K3 Sektoral di PT Kreasi Ultimate Berjaya",
        "paragraphs": [
          "PT Kreasi Ultimate Berjaya menyediakan layanan terpadu mencakup pelatihan in-house yang dikustomisasi sesuai proses kerja sektor Anda, audit kesiapan sertifikasi SMK3, hingga konsultasi penyusunan dokumen keselamatan kerja komprehensif."
        ]
      }
    ],
    "faqs": [
      {
        "question": "Apa bahaya paling kritis yang dihadapi pekerja di sektor Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm)?",
        "answer": "Bahaya dominan meliputi risiko mekanik permesinan, paparan lingkungan fisik ekstrem, potensi kebakaran/ledakan, dan kelelahan kerja yang membutuhkan mitigasi bertingkat."
      },
      {
        "question": "Regulasi apa yang wajib dipatuhi oleh manajemen di sektor Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm)?",
        "answer": "Kepatuhan mengacu pada SMKP Minerba, Sistem Manajemen Keselamatan Migas & SMK3 PP 50/2012, UU No. 1 Tahun 1970, serta peraturan menteri sektoral terkait yang mengikat."
      },
      {
        "question": "Bagaimana cara menyelenggarakan pelatihan in-house K3 khusus sektor Pembangkit Listrik Tenaga Bayu / Angin (PLTB Wind Farm)?",
        "answer": "Anda dapat menghubungi konsultan PT Kreasi Ultimate Berjaya via WhatsApp untuk mendiskusikan silabus modular, jadwal pelaksanaan, dan simulasi studi kasus lapangan fasilitas Anda."
      }
    ],
