    "answer": "Penerapan K3 di Sektor Pabrik Cat, Tinta Cetak, Pelarut & Resin Sintetis dirancang untuk mengelola risiko kecelakaan spesifik dan penyakit akibat kerja di sektor Pabrik Cat, Tinta Cetak, Pelarut & Resin Sintetis melalui integrasi SMK3 PP 50/2012, ISO 45001 & Norma Teknis Kemnaker RI serta penempatan personel K3 bersertifikasi resmi.",
