    "description": "Panduan implementasi K3 sektor Pabrik Pembuatan Kardus Gelombang & Box Kemasan: identifikasi bahaya dominan, kerangka regulasi SMK3 PP 50/2012, ISO 45001 & Norma Teknis Kemnaker RI, kebutuhan lisensi personil, dan program mitigasi kecelakaan.",
    "answer": "Penerapan K3 di Sektor Pabrik Pembuatan Kardus Gelombang & Box Kemasan dirancang untuk mengelola risiko kecelakaan spesifik dan penyakit akibat kerja di sektor Pabrik Pembuatan Kardus Gelombang & Box Kemasan melalui integrasi SMK3 PP 50/2012, ISO 45001 & Norma Teknis Kemnaker RI serta penempatan personel K3 bersertifikasi resmi.",
