    "answer": "Penerapan K3 di Sektor Laboratorium Klinik Pengujian Medis & Diagnostik dirancang untuk mengelola risiko kecelakaan spesifik dan penyakit akibat kerja di sektor Laboratorium Klinik Pengujian Medis & Diagnostik melalui integrasi Permenkes No. 66/2016 (K3RS), Standar Akreditasi & SMK3 PP 50/2012 serta penempatan personel K3 bersertifikasi resmi.",
