    "answer": "Penerapan K3 di Sektor Perkebunan Kelapa Sawit & Pabrik Minyak Kelapa Sawit (PKS) dirancang untuk mengelola risiko kecelakaan spesifik dan penyakit akibat kerja di sektor Perkebunan Kelapa Sawit & Pabrik Minyak Kelapa Sawit (PKS) melalui integrasi Permenkes No. 66/2016 (K3RS), Standar Akreditasi & SMK3 PP 50/2012 serta penempatan personel K3 bersertifikasi resmi.",
